import urllib.parse

def apply_rewrite_rules(rules, urls):
    def parse_url(url):
        parsed = urllib.parse.urlparse(url)
        return {
            'scheme': parsed.scheme,
            'host': parsed.hostname or '',
            'port': parsed.port if parsed.port else (80 if parsed.scheme == 'http' else 443),
            'path': parsed.path or '/',
            'query': parsed.query or '',
            'full_path_and_query': parsed.path + ('?' + parsed.query if parsed.query else '')
        }

    def reconstruct_url(scheme, host, port, path, query):
        # Handle port: don't include standard ports
        if port in (80, 443):
            if scheme == 'http' and port == 80:
                port_str = ''
            elif scheme == 'https' and port == 443:
                port_str = ''
            else:
                port_str = ':' + str(port)
        else:
            port_str = ':' + str(port)

        if not query:
            return f"{scheme}://{host}{port_str}{path}"
        else:
            return f"{scheme}://{host}{port_str}{path}?{query}"

    def check_host_rule(rule, url):
        match_value = rule['match_value']
        host = url['host']

        if host == match_value:
            return True

        # Check for subdomain matching with "*.example.com" pattern
