                if host.endswith(domain_part):
                    parts = host.split('.')
                    pattern_parts = domain_part.split('.')

                    # host should have more parts than pattern_parts
                    if len(parts) > len(pattern_parts):
                        return True

        return False

    def check_path_prefix_rule(rule, url):
        match_value = rule['match_value']
        path = url['path']

        # Need to handle case where URL might not have a leading "/"
        if path and not path.startswith('/'):
