        query = url['query'] or ''

        # Add to query string
        if query:
            new_query = f"{query}&{action_value}"
        else:
            new_query = action_value

        return {
            'scheme': url['scheme'],
            'host': url['host'],
            'port': url.get('port', (80 if url['scheme'] == 'http' else 443)),
            'path': url['path'],
            'query': new_query
        }

